<?php

namespace App\Http\Controllers\Api\V1;

use App\Models\User;
use Illuminate\Auth\Events\Verified;
use Illuminate\Http\JsonResponse;
use Illuminate\Http\Request;

class EmailVerificationController extends Controller
{
    /**
     * Mark the requested user's email address as verified.
     *
     * The route is protected by Laravel's "signed" middleware, so only URLs
     * generated by this application (via the verification notification)
     * are accepted.
     */
    public function verify(Request $request, string $id, string $hash): JsonResponse
    {
        $user = User::find($id);

        if (! $user || ! hash_equals(sha1($user->getEmailForVerification()), $hash)) {
            return $this->errorResponse('The email verification link is invalid.', [], 403);
        }

        if ($user->hasVerifiedEmail()) {
            return $this->successResponse('Email address already verified.');
        }

        if ($user->markEmailAsVerified()) {
            event(new Verified($user));
        }

        return $this->successResponse('Email address verified successfully.');
    }

    /**
     * Resend the email verification notification to the authenticated user.
     */
    public function resend(Request $request): JsonResponse
    {
        $user = $request->user();

        if ($user->hasVerifiedEmail()) {
            return $this->errorResponse('Email address already verified.', [], 409);
        }

        $user->sendEmailVerificationNotification();

        return $this->successResponse('A new verification link has been sent.', [], 202);
    }
}
